def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    own = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_d = 0
    own_d = 0
    for i in range(n):
        if opp[i] == 'D':
            opp_d += 1
        if own[i] == 'D':
            own_d += 1

    last_own = own[-1]
    last_opp = opp[-1]

    opp_streak = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        opp_streak += 1
        i -= 1

    own_c_streak = 0
    i = n - 1
    while i >= 0 and own[i] == 'C':
        own_c_streak += 1
        i -= 1

    exploit = 0
    punish = 0

    recent_start = max(0, n - 10)
    recent_opp_d = 0
    recent_exploit = 0

    for i in range(1, n):
        if own[i - 1] == 'D':
            if opp[i] == 'D':
                punish += 1
        else:
            if opp[i] == 'D':
                exploit += 1

    for i in range(recent_start, n):
        if opp[i] == 'D':
            recent_opp_d += 1
        if i >= 1 and own[i - 1] == 'C' and opp[i] == 'D':
            recent_exploit += 1

    max_exploit = 2 + n // 30
    hostile = False

    if opp_d >= 3 and opp_d >= n // 2:
        hostile = True
    if recent_opp_d >= 6:
        hostile = True
    if opp_streak >= 4:
        hostile = True
    if n > 25 and opp_d * 20 > n * 9:
        hostile = True
    if exploit > max_exploit and exploit >= own_d:
        hostile = True

    if hostile:
        return 'D'

    if n >= 98:
        return 'D'

    if opp_streak >= 2:
        return 'D'

    if n >= 95:
        if last_own == 'D':
            return 'C'
        if last_opp == 'D':
            if recent_exploit >= 2 or exploit >= 3:
                return 'D'
            return 'C'
        return 'C'

    if last_own == 'D':
        return 'C'

    if last_opp == 'D':
        if recent_exploit >= 2 or exploit >= 3:
            return 'D'
        if n > 30 and opp_d >= 5 and recent_opp_d >= 4:
            return 'D'
        return 'C'

    balanced = (own_d > opp_d) or (own_d == 0 and opp_d == 0)
    max_probe_exploit = 2 + n // 40

    if (
        n >= 20
        and own_c_streak >= 2
        and opp_streak == 0
        and recent_opp_d <= 2
        and recent_exploit <= 1
        and exploit <= max_probe_exploit
        and punish == 0
        and own_d * 2 <= n
        and balanced
    ):
        if rng.random() < 0.9:
            return 'D'

    return 'C'
